def run(args, stdin=None):
    p = subprocess.run(["./executable"]+args, input=stdin, capture_output=True, text=True)
    return p
tmp=tempfile.mkdtemp()
def mkfile(fname, src):
    path=os.path.join(tmp,fname)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    open(path,'w').write(src)
    return path
def abi(src, fname="T.sol"):
    pa=mkfile(fname, src)
    p=run([pa,"--emit","abi"])
    if p.returncode!=0:
        print("ERR",repr(src[:150]), repr(p.stderr[:4000]))
        return None
    j=json.loads(p.stdout)
    print(json.dumps(j, indent=2))
    print("---")
    return j

